import { test, expect } from '@playwright/test';
import { STATUS, openWithStatus, expectCurrentStatus } from './publish-confirmation.helpers';

test.use({ serviceWorkers: 'block' });

test('Активное объявление — «העסק פורסם בהצלחה!» и «צפה במודעה» #243006 @desktop @prod-safe', async ({ page }) => {
  const { passed } = await openWithStatus(page, STATUS.active);

  await expect(page.getByRole('heading', { name: 'העסק פורסם בהצלחה!' })).toBeVisible();
  await expect(page.getByText(/כעת פורסם/)).toBeVisible();
  await expect(page.getByText(/ממתינה לאישור/), 'нет «ממתינה לאישור»').toHaveCount(0);
  await expect(page.getByRole('link', { name: 'צפה במודעה' })).toBeVisible();

  await expectCurrentStatus(page, STATUS.active);
  expect(passed, 'не-GET не дошли до сервера').toEqual([]);
});
